#!/usr/bin/env node
/**
 * flowforge-sync.mjs - fan site.config.js out to the surfaces that cannot
 * import it.
 *
 * The JS surfaces read site.config.js directly (no drift possible). The
 * surfaces that CANNOT import it - the two engine-owned config files
 * (prestruct's web/ssr.config.js is an adapter, but freestruct's YAML is not
 * JS; Jekyll's _config.yml, robots.txt, and site.webmanifest are data) - are
 * GENERATED here from the one identity file. A generated file is never edited
 * by hand; `--check` fails when one has drifted, so the drift class the brand
 * census gate names is caught at its source.
 *
 *   node scripts/flowforge-sync.mjs           write every derived file
 *   node scripts/flowforge-sync.mjs --check   refuse if any has drifted
 *
 * Every write is deterministic: same config -> same bytes, no wall clock.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import site from '../site.config.js'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')

const BANNER = (src) =>
  `# GENERATED by flowforge sync from ${src} - edit that file, then run \`npm run sync\`.\n# Hand edits here are drift and fail \`npm run sync:check\`.\n`

// Each target: a path, and a render(site) -> string. Deterministic, no clock.
const TARGETS = [
  {
    path: 'docs/_config.yml',
    render: (s) => `${BANNER('site.config.js')}
title: ${s.name}
baseurl: "${s.docs.baseurl}" # the docs deploy path (GitHub Pages project path)
url: "${s.docs.host}"
description: ${s.description}

# Identity the layout renders (docs/_layouts/default.html reads these; the
# brand census gate keeps the layout from hardcoding any of them).
repo: ${s.repo}
brand_accent: ${s.wordmark.accent}
brand_rest: ${s.wordmark.rest}
maker_label: ${s.maker.label}
maker_url: ${s.maker.url}
org_name: ${s.org.name}
org_url: ${s.org.url}
site_url: ${s.url}
docs_url: ${s.docs.url}
theme_key: ${s.theme.themeKey}
scheme_key: ${s.theme.schemeKey}

markdown: kramdown
highlighter: rouge
permalink: :title

# pretty = /path/ (with trailing slug); individual frontmatter overrides.
exclude: ['README.md', 'Gemfile', 'Gemfile.lock', 'tmp', 'pagefind*']

kramdown:
  syntax_highlighter: rouge
  syntax_highlighter_opts:
    default_lang: plaintext
    css_class: 'highlight'
  toc_levels: [1, 2, 3, 4, 5, 6]
  auto_ids: true
  auto_id_prefix: ''

plugins:
  - jekyll-redirect-from
`,
  },
  {
    path: 'docs/freestruct.config.yml',
    render: (s) => `${BANNER('site.config.js')}
site:
  name: ${s.name}
  url: ${s.docs.url}
  description: ${s.description}

# Author identity - ships as a schema.org Person under "founder" on the
# injected Organization JSON-LD block (the engine edition template carries the
# {{authorJson}} seam).
author:
  name: ${s.org.name}
  url: ${s.org.url}

# Maintainer identity - custom JSON-LD appended after the built-in
# Organization + WebSite pair (the legacy list form).
jsonLd:
  - "@type": Person
    name: ${s.author}
    url: ${s.repo}
    jobTitle: ${s.name} maintainer

twitter:
  card: summary_large_image
`,
  },
  {
    path: 'web/public/robots.txt',
    render: (s) => `${BANNER('site.config.js')}
# crawler policy - all the way open, it's a library site
User-agent: *
Allow: /

Sitemap: ${s.url}/sitemap.xml
`,
  },
  {
    path: 'web/public/site.webmanifest',
    render: (s) =>
      JSON.stringify(
        {
          name: s.name,
          short_name: s.name,
          description: s.description,
          start_url: '/',
          display: 'standalone',
          background_color: '#10131a',
          theme_color: '#10131a',
          lang: 'en',
          icons: [
            { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
            { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
            { src: '/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
          ],
        },
        null,
        2
      ) + '\n',
  },
]

const check = process.argv.includes('--check')
let drifted = 0

for (const t of TARGETS) {
  const abs = join(ROOT, t.path)
  const next = t.render(site)
  const prev = existsSync(abs) ? readFileSync(abs, 'utf8') : null
  if (prev === next) {
    console.log(`sync: ${t.path} up to date`)
    continue
  }
  if (check) {
    console.error(`sync: ${t.path} has DRIFTED from site.config.js - run \`npm run sync\``)
    drifted++
  } else {
    writeFileSync(abs, next)
    console.log(`sync: wrote ${t.path}`)
  }
}

if (check && drifted) {
  console.error(`sync:check: FAIL (${drifted} drifted file(s))`)
  process.exit(1)
}
console.log(check ? 'sync:check: PASS (all derived surfaces current)' : 'sync: PASS (derived surfaces written)')
